<?php
declare(strict_types=1);require_once __DIR__.'/_auth.php';require_once __DIR__.'/../vendor/autoload.php';
use EnglAI\Mvp\ClassroomService;require_admin();$pdo=db();$cid=(int)($_GET['classroom_id']??0);$teacher=(string)($_SESSION['admin_username']??env_value('ADMIN_USERNAME','admin'));try{$classroom=(new ClassroomService($pdo))->requireOwned($cid,$teacher);}catch(Throwable){http_response_code(404);exit('Classroom tidak ditemukan.');}$q=$pdo->prepare('SELECT r.*,m.display_name,s.level,a.title,a.content_json FROM speaking_recordings r JOIN classroom_members m ON m.id=r.member_id JOIN speaking_sessions s ON s.id=r.session_id JOIN learning_activities a ON a.id=r.task_id WHERE r.classroom_id=? ORDER BY r.created_at DESC LIMIT 100');$q->execute([$cid]);$rows=$q->fetchAll();function sh(mixed $v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Speaking Review · EnglAI</title><link rel="stylesheet" href="/assets/css/mvp.css"></head><body><div class="stars" aria-hidden="true"></div><header class="nav"><a class="brand" href="/admin/dashboard.php"><span class="brand-mark">E</span>EnglAI</a><a class="button secondary" href="/admin/classroom.php?id=<?=$cid?>#self-learning">← Classroom</a></header><main class="shell"><section class="card"><span class="eyebrow">Teacher Review</span><h1>Speaking Responses · <?=sh($classroom['name'])?></h1><?php if(!$rows):?><div class="empty">Belum ada Speaking recording.</div><?php endif;?><?php foreach($rows as $r):$content=json_decode((string)$r['content_json'],true)?:[];$assessment=json_decode((string)($r['assessment_json']??''),true)?:[];?><article class="analysis-item" style="margin:16px 0"><h3><?=sh($r['display_name'])?> · <?=sh(ucfirst($r['level']))?></h3><p><b><?=sh($r['title'])?></b> — <?=sh($content['prompt']??'')?></p><audio controls preload="none" src="/admin/speaking_audio.php?id=<?=(int)$r['id']?>"></audio><p>Transcript: <?=sh($r['final_transcript']??'Needs Teacher review')?></p><p>Status: <?=sh($r['assessment_status'])?><?php if(isset($assessment['total_score'])):?> · Score <?=sh($assessment['total_score'])?>/100<?php endif;?></p></article><?php endforeach;?></section></main></body></html>
